<template>
  <div class="pricing-container">
    <div class="pricing-table-section">
      <div
        v-for="(plan, pIndex) in activeService.packages"
        :key="pIndex"
        class="pricing-table"
        :class="{ 'pricing-table--featured': pIndex === 1 }"
      >
        <div class="plan-header">
          <span>{{ plan.name }}</span>
        </div>
        <div class="price"><span class="price__value">{{ plan.price }}</span></div>
        <div class="pricing-table__rule"></div>
        <ul class="features" :aria-label="`${plan.name} features`">
          <li v-for="(feature, fIndex) in plan.features" :key="fIndex">
            <span class="feature-icon" :class="`${plan.class}-package`" aria-hidden="true">+</span>
            <span>{{ feature }}</span>
          </li>
        </ul>
        <button
          class="cta-button"
          :class="`${plan.class}-package`"
          type="button"
          :aria-label="`Place an order for ${plan.name}`"
          @click="openOrderModal(plan)"
        >
          <span>Order {{ plan.name }}</span>
          <span aria-hidden="true">↗</span>
        </button>
      </div>
    </div>

    <dialog
      ref="orderDialog"
      class="pricing-order-modal"
      aria-labelledby="pricing-order-title"
      @click.self="closeOrderModal"
      @cancel.prevent="closeOrderModal"
    >
      <div class="pricing-order-modal__header">
        <div>
          <p class="pricing-order-modal__eyebrow">{{ activeService.service }}</p>
          <h2 id="pricing-order-title">Place an order</h2>
        </div>
        <button
          class="pricing-order-modal__close"
          type="button"
          aria-label="Close order form"
          :disabled="submitting"
          @click="closeOrderModal"
        >
          &times;
        </button>
      </div>

      <p v-if="selectedPlan" class="pricing-order-modal__package">
        {{ selectedPlan.name }} · {{ selectedPlan.price }}
      </p>

      <form class="pricing-order-form" @submit.prevent="submitOrder">
        <label for="pricing-order-name">Your name</label>
        <input
          id="pricing-order-name"
          ref="orderName"
          v-model.trim="form.name"
          type="text"
          autocomplete="name"
          required
          :disabled="submitting"
        />

        <label for="pricing-order-email">Email address</label>
        <input
          id="pricing-order-email"
          v-model.trim="form.email"
          type="email"
          autocomplete="email"
          required
          :disabled="submitting"
        />

        <label for="pricing-order-phone">Phone number <span>(optional)</span></label>
        <input
          id="pricing-order-phone"
          v-model.trim="form.phone"
          type="tel"
          autocomplete="tel"
          :disabled="submitting"
        />

        <label for="pricing-order-details">Project details <span>(optional)</span></label>
        <textarea
          id="pricing-order-details"
          v-model.trim="form.details"
          rows="3"
          :disabled="submitting"
        ></textarea>

        <input
          v-model="form.honeypot"
          class="pricing-order-form__honeypot"
          type="text"
          name="_honey"
          tabindex="-1"
          autocomplete="off"
          aria-hidden="true"
        />

        <button type="submit" :disabled="submitting">
          {{ submitting ? 'Sending…' : 'Submit order request' }}
        </button>
        <p class="pricing-order-form__status" aria-live="polite">{{ status }}</p>
      </form>
    </dialog>
  </div>
</template>

<script>
const ORDER_ENDPOINT = 'https://formsubmit.co/ajax/d7a1ab1e3c506057146c9461a0adf40e';

export default {
  name: 'PricingTableSection',
  props: {
    // Renamed for clarity: this represents ONE service (e.g. Mobile)
    activeService: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      selectedPlan: null,
      submitting: false,
      status: '',
      form: {
        name: '',
        email: '',
        phone: '',
        details: '',
        honeypot: '',
      },
    };
  },
  methods: {
    openOrderModal(plan) {
      this.selectedPlan = plan;
      this.status = '';
      this.form = {
        name: '',
        email: '',
        phone: '',
        details: '',
        honeypot: '',
      };
      this.$refs.orderDialog.showModal();
      this.$nextTick(() => this.$refs.orderName.focus());
    },
    closeOrderModal() {
      if (!this.submitting && this.$refs.orderDialog.open) {
        this.$refs.orderDialog.close();
        this.selectedPlan = null;
      }
    },
    async submitOrder() {
      if (this.submitting || !this.selectedPlan) return;

      this.submitting = true;
      this.status = '';

      try {
        const response = await fetch(ORDER_ENDPOINT, {
          method: 'POST',
          headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            _subject: `Package order: ${this.activeService.service} — ${this.selectedPlan.name}`,
            _replyto: this.form.email,
            customer_name: this.form.name,
            customer_email: this.form.email,
            customer_phone: this.form.phone,
            service: this.activeService.service,
            package: this.selectedPlan.name,
            listed_price: this.selectedPlan.price,
            project_details: this.form.details,
            _honey: this.form.honeypot,
          }),
        });

        const result = await response.json();
        if (!response.ok || (result.success !== 'true' && result.success !== true)) {
          throw new Error(result.message || `Order request failed with status ${response.status}`);
        }

        this.status = 'Your order request has been sent. We will be in touch soon.';
        this.form = {
          name: '',
          email: '',
          phone: '',
          details: '',
          honeypot: '',
        };
      } catch (error) {
        this.status = 'We could not send your order request. Please try again later.';
        console.error('Package order request failed.', error);
      } finally {
        this.submitting = false;
      }
    },
  }
};
</script>